INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein IT-Hoax immer einen Virus enthält?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Social Engineering sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme hilft mir, eine falsche IT-Warnung zu erkennen?', 3, '[{"text": "Quelle überprüfen", "correct": true, "because": "Verifiziert Echtheit"}, {"text": "Sofort weiterleiten", "correct": false, "because": "Verbreitet Hoax"}, {"text": "Ignorieren", "correct": false, "because": "Kann Risiko übersehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine E-Mail verdächtig?', 5, '[{"text": "Dringlichkeit", "correct": true, "because": "Drängt zu schnellem Handeln"}, {"text": "Unbekannter Absender", "correct": true, "because": "Häufig bei Hoaxes"}, {"text": "Hohe Qualität", "correct": false, "because": "Nicht entscheidend"}, {"text": "Persönlicher Ton", "correct": false, "because": "Kann täuschen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Hoax kann Daten stehlen. b) Jede Warnung ist echt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ignoriert Falschmeldungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine IT-Warnung prüfe?', 4, '[{"text": "Absenderadresse", "correct": false, "because": "Wichtig für Echtheit"}, {"text": "Links im Text", "correct": false, "because": "Können gefährlich sein"}, {"text": "Schriftfarbe", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Sicherheitswarnung ernst ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind Hoaxes"}, {"text": "Ja", "correct": false, "because": "Falschmeldungen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten wähle ich bei einem verdächtigen Ticket?', 3, '[{"text": "Eskalation prüfen", "correct": true, "because": "Experten klären Echtheit"}, {"text": "Sofort löschen", "correct": false, "because": "Kann echt sein"}, {"text": "Weiterleiten", "correct": false, "because": "Verbreitet Hoax"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine IT-Meldung glaubwürdig?', 5, '[{"text": "Verifizierte Quelle", "correct": true, "because": "Bestätigt Echtheit"}, {"text": "Technische Details", "correct": true, "because": "Zeigen Fachwissen"}, {"text": "Emotionale Sprache", "correct": false, "because": "Typisch für Hoaxes"}, {"text": "Viele Weiterleitungen", "correct": false, "because": "Hinweis auf Hoax"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Hoaxes oft Panik erzeugen und b) sie immer technisch sind. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ignoriert Social Engineering"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Sicherheitsmeldung zu prüfen?', 4, '[{"text": "Offizielle Quelle", "correct": false, "because": "Bestätigt Echtheit"}, {"text": "Technische Analyse", "correct": false, "because": "Klärt Details"}, {"text": "Persönliches Gefühl", "correct": true, "because": "Subjektiv, nicht verlässlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Hoaxes immer leicht zu erkennen?', 2, '[{"text": "Nein", "correct": true, "because": "Gut gemacht täuschen sie"}, {"text": "Ja", "correct": false, "because": "Können raffiniert sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen vor IT-Falschmeldungen?', 4, '[{"text": "Schulungen", "correct": true, "because": "Erhöhen Awareness"}, {"text": "Kritische Prüfung", "correct": true, "because": "Verhindert Verbreitung"}, {"text": "Schnelle Reaktion", "correct": false, "because": "Kann Hoax fördern"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Hoax nur Spaß ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann Schaden anrichten"}, {"text": "Ja", "correct": false, "because": "Ignoriert Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich eine Warnung überprüfe?', 3, '[{"text": "Echtheit bestätigen", "correct": true, "because": "Schützt vor Hoaxes"}, {"text": "Sofort handeln", "correct": false, "because": "Riskant ohne Prüfung"}, {"text": "Weiterleiten", "correct": false, "because": "Kann Hoax verbreiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hoaxes nutzen oft Angst. b) Sie sind immer harmlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ignoriert Schaden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten wähle ich bei einem Phishing-Verdacht?', 4, '[{"text": "Nicht klicken, melden", "correct": true, "because": "Verhindert Schaden"}, {"text": "Links öffnen", "correct": false, "because": "Riskiert Datenverlust"}, {"text": "Kollegen warnen", "correct": false, "because": "Nur nach Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Hoax immer technisches Wissen braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Social Engineering reicht"}, {"text": "Ja", "correct": false, "because": "Psychologie oft genug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Ticket-System bei Hoax-Prüfung?', 5, '[{"text": "Nachverfolgbarkeit", "correct": true, "because": "Dokumentiert Vorgänge"}, {"text": "Priorisierung", "correct": true, "because": "Sortiert Dringlichkeit"}, {"text": "Schnelle Lösung", "correct": false, "because": "Nicht primär"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Hoaxes nur E-Mails?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Social Media"}, {"text": "Ja", "correct": false, "because": "Mehr Kanäle möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario zeigt einen typischen IT-Hoax?', 4, '[{"text": "Fake-Virus-Warnung", "correct": true, "because": "Nutzt Angst aus"}, {"text": "Echte Update-Meldung", "correct": false, "because": "Kein Hoax"}, {"text": "Hardware-Anleitung", "correct": false, "because": "Kein Täuschungsversuch"}]');
